<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use App\Models\{CrmFinancialRegister,User};use App\Services\{ClientRelationsPipeline,PerformanceWorkflow};
class ImportCrmFinancialRegister extends Command {
 protected $signature='crm:import-financial-register {file} {--owner-map=} {--actor=}';protected $description='Import source PO/invoice registers with provenance; never infer cash or recognized revenue';
 public function handle():int{$data=json_decode(file_get_contents($this->argument('file')),true,512,JSON_THROW_ON_ERROR);$map=json_decode(file_get_contents($this->option('owner-map')),true,512,JSON_THROW_ON_ERROR);$actor=User::findOrFail($this->option('actor'));abort_unless(ClientRelationsPipeline::member($actor)&&$actor->isLineManager(),403);if(($data['source_id']??null)!=='1ydsMLK86iDG5XPp1PcC3_qjh_2CjeJ_-')throw new \RuntimeException('Unexpected workbook');$added=0;
 DB::transaction(function()use($data,$map,$actor,&$added){foreach($data['rows'] as $row){if(empty($map[$row['sheet']])||!ClientRelationsPipeline::historicalOwner(User::findOrFail($map[$row['sheet']])))throw new \RuntimeException('Confirmed source owner required.');$key=hash('sha256',$data['source_id'].'|financial|'.$row['sheet'].'|'.$row['row']);if(CrmFinancialRegister::where('import_key',$key)->exists())continue;$r=CrmFinancialRegister::create(['import_key'=>$key,'client_name'=>$row['client'],'project_name'=>$row['project'],'owner_id'=>$map[$row['sheet']],'po_amount'=>$row['po_amount'],'po_balance'=>$row['po_balance'],'invoiced_amount'=>$row['invoiced_amount'],'po_status'=>$row['po_status'],'invoice_status'=>$row['invoice_status'],'source_sheet'=>$row['sheet'],'source_row'=>$row['row'],'source_year'=>$row['source_year'],'as_of'=>$row['as_of'],'source_values'=>$row['source_values'],'source_checksum'=>$row['checksum']]);PerformanceWorkflow::record('crm_financial_register',$r->id,$actor->id,'import',[],$r->getAttributes(),'Copied PO/invoice source figures. No cash collection, revenue recognition or missing dates inferred.');$added++;}});$this->info(json_encode(['imported'=>$added,'total'=>CrmFinancialRegister::count()]));return self::SUCCESS;}
}
